<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Website owner setup · <?=htmlspecialchars(APP_NAME)?></title><link rel="stylesheet" href="/assets/styles.css"></head><body><main style="max-width:620px;margin:8vh auto;padding:24px"><section class="modal" style="position:relative;opacity:1;transform:none"><h1>Website owner setup</h1><p class="sub">Create the separate owner account. This is not a seller registration.</p><?php if($ownerExists): ?><p class="error">The website owner account has already been created. Please use the normal login page.</p><a class="btn btn-primary" href="/">Go to marketplace login</a><?php else: ?><form id="ownerSetup"><div class="form-field"><label>Owner full name</label><input name="full_name" required autocomplete="name"></div><div class="form-field"><label>Owner email address</label><input name="email" type="email" required autocomplete="username"></div><div class="form-field"><label>Phone number (optional)</label><input name="phone" autocomplete="tel"></div><div class="form-field"><label>Create owner password (minimum 12 characters)</label><input name="password" type="password" minlength="12" required autocomplete="new-password"></div><div class="form-field"><label>One-time owner setup code</label><input name="setup_token" type="password" minlength="32" required autocomplete="off"></div><button class="btn btn-primary" type="submit">Create separate owner account</button></form><p id="ownerResult" class="sub" aria-live="polite"></p><?php endif; ?></section></main><?php if(!$ownerExists): ?><script>document.getElementById('ownerSetup').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button'),result=document.getElementById('ownerResult');button.disabled=true;result.textContent='Creating owner account…';try{const response=await fetch('/api/owner/setup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const data=await response.json();if(!response.ok)throw new Error(data.error||'Owner setup failed.');form.remove();result.textContent=data.message+' You can now log in using the owner email and password you selected.';result.innerHTML+=' <a href="/">Go to login</a>';}catch(err){result.textContent=err.message;button.disabled=false;}});</script><?php endif; ?></body></html>